G=load(); inp,out=G['Demo pair 1 input'],G['Demo pair 1 output']
H,W=len(inp),len(inp[0])
spec=set(c for row in inp for c in row)-{3}
mmap={1:7,8:7,2:4,6:4}
def solve(g, mode='manhattan'):
    h,w=len(g),len(g[0])
    srcs=[]
    for i in range(h):
        for j in range(w):
            if g[i][j] in spec: srcs.append((i,j,g[i][j]))
    res=[row[:] for row in g]
    for i in range(h):
        for j in range(w):
            if g[i][j] in spec: continue
            best=None
            for s in srcs:
                a,b,c=s
                d=min(abs(a-i)+abs(b-j), abs(a-i)+abs(b-j))  # manhattan
                if mode=='cheb': d=max(abs(a-i),abs(b-j))
                cand=(d,mmap[c])
                if best is None or cand<best: best=cand
            if best and best[0]<=1:
                res[i][j]=best[1]
    return res
