#  1: orth->7, diag->4 ; 2: all->4 ; 6: anti-diag(-1,1),(1,-1)->7 else 4 ; 8: orth->7, diag->4
MAP={
 1:{(0,-1):7,(0,1):7,(-1,0):7,(1,0):7,(-1,-1):4,(-1,1):4,(1,-1):4,(1,1):4},
 2:{(a,b):4 for a in(-1,0,1) for b in(-1,0,1)},
 6:{(1,-1):7,(-1,1):7,(0,-1):4,(0,1):4,(-1,0):4,(1,0):4,(-1,-1):4,(1,1):4},
 8:{(0,-1):7,(0,1):7,(-1,0):7,(1,0):7,(-1,-1):4,(-1,1):4,(1,-1):4,(1,1):4}
}
def solve(g,prio=[1,2,6,8]):
    H,W=len(g),len(g[0])
    cntv=Counter(v for r in g for v in r); bg=cntv.most_common(1)[0][0]
    sp=[(i,j,g[i][j]) for i in range(H) for j in range(W) if g[i][j] in MAP]
    res=[r[:] for r in g]
    def cands(i,j):
        out=[]
        for a,b,c in sp:
            if c in MAP and (i-a,j-b) in MAP[c]: out.append(c)
        return out
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg: continue
            cs=cands(i,j)
            if cs:
                best=min(cs,key=lambda c: prio.index(c))
                res[i][j]=best
    return res
