G=load()

def f(gi):
    H,W=len(gi),len(gi[0])
    bg=Counter(v for r in gi for v in r).most_common(1)[0][0]
    specials=[(a,b,c) for a in range(H) for b in range(W) if gi[a][b]!=bg]
    out=[row[:] for row in gi]
    # nearest marker wins (min chebyshev dist, then lower index); paint = 7 if orthogonally adjacent to winner else 4
    win=[[None]*W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            cands=[]
            for idx,(ma,mb,c) in enumerate(specials):
                dd=max(abs(i-ma),abs(j-mb))
                if dd<=1:
                    pc=7 if abs(i-ma)+abs(j-mb)==1 else 4
                    cands.append((dd,idx,pc))
            if cands:
                win[i][j]=min(cands,key=lambda z:(z[0],z[1]))[2]
    for i in range(H):
        for j in range(W):
            if gi[i][j]==bg and win[i][j] is not None:
                out[i][j]=win[i][j]
    return out

