def score(keyf,tf):
    total=0
    for d in range(1,7):
        gi,go=G[f'Demo pair {d} input'],G[f'Demo pair {d} output']
        H,W=len(gi),len(gi[0])
        cntv=Counter(v for r in gi for v in r); bg=cntv.most_common(1)[0][0]
        specials=[(a,b,c) for a in range(H) for b in range(W) if gi[a][b]!=bg]
        okc=True
        for i in range(H):
            for j in range(W):
                if gi[i][j]!=bg: continue
                cands=[]
                for ma,mb,_c in specials:
                    da,db=i-ma,j-mb
                    dd_m=max(abs(da),abs(db))  # cheb
                    if dd_m<=1:
                        cands.append((keyf(abs(da),abs(db)),tf(abs(da),db,ma,mb,i,j,idx:=specials.index((ma,mb))),go[i][j]))
                if cands:
                    best=min(cands)
                    if best[-1]!=best[0]: okc=False
                else:
                    if go[i][j]!=bg: okc=False
        total+=okc
    return total

