# Hypothesis R4: nearest special (Chebyshev dist 1) wins. Paint 7 iff orthogonally adjacent to winner; else 4. Ties -> earlier marker wins.
def solve(gi, verbose=False):
    H,W=len(gi),len(gi[0])
    cntv=Counter(v for r in gi for v in r); bg=cntv.most_common(1)[0][0]
    specials=[(a,b,c) for a in range(H) for b in range(W) if gi[a][b]!=bg]
    out=[row[:] for row in gi]
    for i in range(H):
        for j in range(W):
            cands=[]
            for idx,(ma,mb,_c) in enumerate(specials):
                da,db=i-ma,j-mb
                dd=max(abs(da),abs(db))
                if dd<=1:
                    pc=7 if abs(da)+abs(db)==1 else 4
                    cands.append((dd,idx,pc))
            if cands:
                dd,idx,pc=min(cands,key=lambda z:(z[0],z[1]))
                out[i][j]=pc
    return out

