    cnt=Counter(v for r in gi for v in r); bg=cnt.most_common(1)[0][0]
    out=[row[:] for row in gi]
    claims=defaultdict(set)
    for a in range(H):
        for b in range(W):
            v=gi[a][b]
            if v!=bg:
                offs=[(-1,-1),(-1,1),(1,-1),(1,1)] if v%2==0 else [(-1,0),(0,1),(0,-1),(1,0)]
                col=4 if v%2==0 else 7
                for di,dj in offs:
                    x,y=a+di,b+dj
                    if 0<=x<H and 0<=y<W and gi[x][y]==bg:
                        claims[(x,y)].add(col)
    for (x,y),cols in claims.items():
        out[x][y]=list(cols)[0] if len(cols)==1 else 4
    return out

